'use strict';
function rejectCandidate(){const a=candidate();if(!a||a.status!=='ready')return;modal('拒绝这个候选？','当前方案不会变化，候选与执行过程仍会保留。',`<p class="form-note">候选 ${esc(a.id)} · 基于 ${esc(a.baseId)}</p><label class="radio-option"><input type="radio" name="reject" value="不符合修改描述" checked>不符合修改描述</label><label class="radio-option"><input type="radio" name="reject" value="图面排布不满意">图面排布不满意</label><label class="radio-option"><input type="radio" name="reject" value="选区需要重新调整">选区需要重新调整</label><textarea class="prompt" id="rejectNote" maxlength="300" placeholder="补充原因（可选）"></textarea>`,`<button class="btn" data-close>继续比较</button><button class="btn danger" id="confirmReject">确认拒绝</button>`);$('confirmReject').onclick=()=>{a.status='rejected';a.rejectReason=document.querySelector('input[name=reject]:checked').value+($('rejectNote').value.trim()?'；'+$('rejectNote').value.trim():'');addEvent('candidate.rejected','拒绝候选，当前版本不变',{candidate:a.id,reason:a.rejectReason,current_head:state.headId},'decision');closeModal();renderCompare();updateChrome();scheduleSave();toast(`已拒绝 ${a.id}，当前仍是 ${state.headId}`)}}
function renderHistory(){if(!selectedRevision||!rev(selectedRevision))selectedRevision=state.headId;const selected=rev(selectedRevision);$('historyCount').textContent=`${state.revisions.length} 个版本`;$('lineageStrip').innerHTML='<span>当前会话谱系</span>'+state.revisions.map((r,i)=>`${i?'<span>→</span>':''}<span class="lineage-node ${r.id===state.headId?'head':''}" title="${esc(r.type==='restore'?'恢复自 '+r.restoreFrom:r.title)}">${r.id}${r.type==='restore'?' ↶ '+r.restoreFrom:''}</span>`).join('');$('revisionList').innerHTML=[...state.revisions].reverse().map(r=>`<div class="revision ${r.id===state.headId?'current':''} ${r.id===selectedRevision?'selected':''} ${r.type==='restore'?'restore':''}" role="button" tabindex="0" data-revision="${r.id}"><div class="between"><strong>${r.id} · ${r.type==='import'?'初始版本':r.type==='restore'?'恢复版本':'修改版本'}</strong>${r.id===state.headId?'<span class="pill teal" style="font-size:9px">当前</span>':''}</div><div class="rev-description">${esc(r.title)}${r.type==='restore'?`<br>内容来自 ${r.restoreFrom} · 父版本 ${r.parent}`:''}</div><div class="rev-time">${niceTime(r.time)}</div></div>`).join('');$('revisionList').querySelectorAll('[data-revision]').forEach(el=>{el.onclick=()=>{selectedRevision=el.dataset.revision;renderHistory()};el.onkeydown=e=>{if(e.key==='Enter'||e.key===' '){e.preventDefault();el.click()}}});$('historyDetail').innerHTML=`<div class="panel"><div class="history-detail-header between"><div><h3>${selected.id} · ${esc(selected.title)}</h3><p>${selected.id===state.headId?'当前工作版本':'历史版本 · 只读查看'} · ${niceTime(selected.time)}</p></div><span class="pill gray">IMAGE_ONLY</span></div><div class="history-image"><img src="${selected.image}" alt="${selected.id} 历史平面图"></div><div class="history-info"><div><span class="muted">来源关系</span>${selected.parent?'父版本 '+selected.parent:'初始导入'}${selected.restoreFrom?' / 恢复来源 '+selected.restoreFrom:''}</div><div><span class="muted">内容摘要</span><span class="mono tiny">${selected.imageHash?selected.imageHash.slice(0,16)+'…':'此浏览器未提供 SHA-256'}</span></div><div class="flex"><button class="btn" id="compareHistory" ${selected.id===state.headId?'disabled':''}>${icon('compare')}与当前比较</button><button class="btn primary" id="restoreVersion" ${selected.id===state.headId||jobBusy?'disabled':''}>${icon('history')}恢复此版本</button></div></div></div><div class="restore-note">${icon('info')}<span>${selected.id===state.headId?'你正在查看当前版本。选择左侧任意历史版本，再点击“恢复此版本”。':`恢复 ${selected.id} 将创建 r${state.revisions.length}；当前 ${state.headId} 和其他历史全部保留，不会被删除。`}</span></div>`;$('restoreVersion').onclick=()=>restoreDialog(selected.id);$('compareHistory').onclick=()=>{const current=head();modal(`${selected.id} 与当前 ${current.id} 比较`,'这里只读查看，不改变当前工作版本。',`<div class="sidebyside"><figure><img src="${selected.image}" alt="历史版本"><figcaption class="small muted" style="margin-top:9px">历史 ${selected.id}</figcaption></figure><figure><img src="${current.image}" alt="当前版本"><figcaption class="small muted" style="margin-top:9px">当前 ${current.id}</figcaption></figure></div>`,`<button class="btn" data-close>关闭比较</button><button class="btn primary" id="restoreFromCompare">恢复 ${selected.id}</button>`,true);$('restoreFromCompare').onclick=()=>{closeModal();restoreDialog(selected.id)}};$('undoVersion').disabled=!head().parent||jobBusy}
function restoreDialog(id,undo=false){if(jobBusy){toast('演示任务还在处理中，请先完成或取消',true);return}const target=rev(id);if(!target||id===state.headId)return;if(state.revisions.length>=LIMITS.revisions){toast('演示最多保留 24 个版本，请先导出工程',true);return}const expected=state.headId,next='r'+state.revisions.length;modal(undo?'撤回上一次版本修改？':`恢复到 ${id} 的内容？`,'这不是删除历史，而是追加一个可以继续编辑的恢复版本。',`<div class="version-transition"><div><span>当前版本</span><strong>${expected}</strong></div>${icon('arrow')}<div><span>新恢复版本</span><strong>${next}</strong></div></div><p class="form-note"><strong>${next}</strong> 的图片内容来自 <strong>${id}</strong>，父版本为 <strong>${expected}</strong>。所有中间版本、被拒绝的候选和过程记录都保留。</p><p class="prototype-note" style="margin-top:14px">几何仍为 IMAGE_ONLY。恢复图片不会恢复未知的建筑尺寸，也不会自动获得 P3 交付资格。未生成的草稿会清空。</p>`,`<button class="btn" data-close>取消</button><button class="btn primary" id="confirmRestore">确认恢复，创建 ${next}</button>`);$('confirmRestore').onclick=async()=>{if(state.headId!==expected){toast('当前版本已变化，请重新确认恢复',true);closeModal();return}const r={id:'r'+state.revisions.length,parent:expected,restoreFrom:id,time:now(),type:'restore',title:undo?'撤回上一次修改，恢复 '+id:'恢复 '+id+' 的内容',description:'追加恢复版本；历史记录未删除。',image:target.image,imageHash:target.imageHash,candidateId:null,geometryStatus:'IMAGE_ONLY'};state.revisions.push(r);state.headId=r.id;selectedRevision=r.id;state.draft.commands=[];state.draft.redo=[];$('prompt').value='';currentImage=await imageOf(r.image);lastLoadedHead=r.id;addEvent('revision.restored','恢复历史内容，追加新版本',{revision:r.id,parent:expected,restore_from:id,history_deleted:false,image_pixels_sha256:r.imageHash},'version');closeModal();rebuildMasks();updateChrome();setPage('history');banner(`已创建恢复版本 ${r.id}，内容来自 ${id}。所有历史仍然保留。`);scheduleSave();toast(`已恢复 ${id} 的内容为 ${r.id}，没有删除任何版本`)}}
function renderAudit(){const accepted=state.attempts.filter(a=>a.status==='accepted').length,rejected=state.attempts.filter(a=>a.status==='rejected').length,restores=state.revisions.filter(r=>r.type==='restore').length;$('auditMetrics').innerHTML=[['生成尝试',state.attempts.length,'全部为程序演示，含取消与失败'],['接受 / 拒绝',accepted+' / '+rejected,'候选不直接覆盖当前方案'],['历史版本',state.revisions.length,restores+' 次恢复；无覆盖删除'],['真实模型调用',0,'未接入 ComfyUI 或其他模型']].map(m=>`<div class="metric"><label>${m[0]}</label><strong>${m[1]}</strong><p>${m[2]}</p></div>`).join('');const filter=$('eventFilter').value;const events=[...state.events].reverse().filter(e=>filter==='all'||e.category===filter);$('eventBody').innerHTML=events.length?events.map(e=>`<tr><td class="time">${niceTime(e.time)}<br><span class="mono" style="font-size:9px">${e.id}</span></td><td><span class="pill ${e.category==='decision'?'teal':e.category==='version'?'amber':'gray'}">${e.category==='decision'?'用户决定':e.category==='version'?'版本变化':'请求与候选'}</span></td><td><span class="event-name">${esc(e.label)}</span><br><span class="mono tiny muted">${esc(e.type)}</span></td><td><details><summary>${icon('log')}展开记录</summary><pre>${esc(JSON.stringify(e.detail,null,2))}</pre></details></td></tr>`).join(''):'<tr><td colspan="4" class="empty">暂无这类记录</td></tr>'}
function downloadBlob(blob,name){const url=URL.createObjectURL(blob);const a=document.createElement('a');a.href=url;a.download=name;document.body.append(a);a.click();a.remove();setTimeout(()=>URL.revokeObjectURL(url),1500)}
function downloadData(url,name){const a=document.createElement('a');a.href=url;a.download=name;document.body.append(a);a.click();a.remove()}
async function exportProject(){await persist();const data={...structuredClone(state),exportInfo:{exportedAt:now(),purpose:'INTERACTION_PROTOTYPE_ONLY',model_executed:false,warning:'Contains user-provided drawing and local history. Keep private.'}};downloadBlob(new Blob([JSON.stringify(data,null,2)],{type:'application/json;charset=utf-8'}),'P2_交互工程_'+state.headId+'.json');toast('工程包含原图和历史；请保存在私有位置')}
function exportAudit(){const data={schema:SCHEMA,exportedAt:now(),sessionId:state.sessionId,currentRevision:state.headId,geometryStatus:'IMAGE_ONLY',modelExecuted:false,revisions:state.revisions.map(({image,...rest})=>rest),attempts:state.attempts.map(({raw,final,diff,mask,protection,strokes,...rest})=>rest),events:state.events};downloadBlob(new Blob([JSON.stringify(data,null,2)],{type:'application/json;charset=utf-8'}),'P2_过程摘要.json')}
async function validateProject(value){if(!value||value.schema!==SCHEMA||!Array.isArray(value.revisions)||!value.revisions.length||value.revisions.length>LIMITS.revisions||!Array.isArray(value.attempts)||value.attempts.length>120||!Array.isArray(value.events)||value.events.length>1000||!value.draft)throw new Error('不是本原型支持的工程格式');if(!Number.isInteger(value.width)||!Number.isInteger(value.height)||value.width<1||value.height<1||value.width*value.height>LIMITS.pixels)throw new Error('图片尺寸超出原型限制');if(typeof value.projectName!=='string'||value.projectName.length>150)throw new Error('项目名称格式错误');for(const ev of value.events)if(!ev||typeof ev.type!=='string'||typeof ev.label!=='string'||typeof ev.time!=='string')throw new Error('事件记录格式错误');const seen=new Set();for(const r of value.revisions){if(typeof r.title!=='string'||typeof r.description!=='string'||!/^r\d+$/.test(r.id)||seen.has(r.id)||r.parent&&!seen.has(r.parent)||r.restoreFrom&&!seen.has(r.restoreFrom))throw new Error('版本关系不完整');if(typeof r.image!=='string'||!/^data:image\/(png|jpeg|webp);base64,/.test(r.image))throw new Error('工程包含不支持的外部图片引用');const im=await imageOf(r.image);if(im.width!==value.width||im.height!==value.height)throw new Error('版本图像尺寸不一致');seen.add(r.id)}if(!seen.has(value.headId))throw new Error('缺少当前版本');if(!Array.isArray(value.draft.commands)||!Array.isArray(value.draft.redo))throw new Error('草稿笔画格式错误');for(const cmd of [...value.draft.commands,...value.draft.redo]){if(!['stroke','rect','clear'].includes(cmd.kind)||cmd.kind!=='clear'&&(!['edit','protect'].includes(cmd.target)||!Array.isArray(cmd.points)||cmd.points.some(p=>!Array.isArray(p)||p.length!==2||!p.every(Number.isFinite))))throw new Error('草稿包含非法笔画')}for(const a of value.attempts){if(!['ready','accepted','rejected','cancelled','running','failed'].includes(a.status))throw new Error('候选状态错误');if(!seen.has(a.baseId))throw new Error('候选来源版本不存在');for(const key of ['raw','final','diff','mask','protection'])if(a[key]&&(!/^data:image\/(png|jpeg|webp);base64,/.test(a[key])))throw new Error('候选含外部图像引用')}return value}
